import{_ as t,o as a,c as o,ag as n}from"./chunks/framework.8tqBsFWt.js";const g=JSON.parse('{"title":"Envelopes","description":"How VERA uses allocation envelopes to plan hours by person and project without gating who can log time.","frontmatter":{"description":"How VERA uses allocation envelopes to plan hours by person and project without gating who can log time."},"headers":[],"relativePath":"reference/concepts/allocations.md","filePath":"reference/concepts/allocations.md"}'),s={name:"reference/concepts/allocations.md"};function r(i,e,l,d,p,h){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="allocations" tabindex="-1">Envelopes <a class="header-anchor" href="#allocations" aria-label="Permalink to &quot;Envelopes {#allocations}&quot;">​</a></h1><p>Envelopes are how Managers plan and distribute work. They are a planning tool — they do not gate who can log time.</p><hr><h2 id="what-is-an-envelope" tabindex="-1">What is an envelope? <a class="header-anchor" href="#what-is-an-envelope" aria-label="Permalink to &quot;What is an envelope? {#what-is-an-envelope}&quot;">​</a></h2><p>An <strong>envelope</strong> is a per-person hour budget on a specific project — or, for Retainer and Agile projects, on a specific period within that project.</p><p>Think of it literally: you have a project with 200 hours in its budget. As a Manager, you put 60 hours in an envelope for Alice, 80 hours for Bob, and 60 hours for Carol. Each person&#39;s envelope is their planned share of the work.</p><ul><li><strong>Alice&#39;s envelope</strong>: 60 hours on Nike Rebrand</li><li><strong>Bob&#39;s envelope</strong>: 80 hours on Nike Rebrand</li><li><strong>Carol&#39;s envelope</strong>: 60 hours on Nike Rebrand</li></ul><p>The underlying data lives in the <code>07. Budgets</code> sheet (despite the sheet name, it stores per-person envelopes, not project budgets). Tool names use &quot;allocation&quot; — e.g. <code>allocate_hours</code>, <code>get_allocations</code> — but the concept is always an envelope.</p><hr><h2 id="envelopes-vs-budgets" tabindex="-1">Envelopes vs. budgets <a class="header-anchor" href="#envelopes-vs-budgets" aria-label="Permalink to &quot;Envelopes vs. budgets&quot;">​</a></h2><p>These two words are often confused. In VERA they mean different things:</p><table tabindex="0"><thead><tr><th>Term</th><th>What it is</th><th>Who sets it</th><th>Where it lives</th></tr></thead><tbody><tr><td><strong>Budget</strong></td><td>Total project hours — the whole pie</td><td>Owner</td><td><code>02. Projects</code>.<code>budget_hours</code></td></tr><tr><td><strong>Envelope</strong></td><td>One person&#39;s slice of that pie</td><td>Manager or Owner</td><td><code>07. Budgets</code></td></tr></tbody></table><blockquote><p><strong>Owners and Managers can have envelopes too.</strong> Any active user — regardless of role — can receive an envelope. An Owner or Manager asking &quot;create an envelope for me on Project X&quot; is a completely valid request. PM assignment and envelopes are separate concerns: being a PM means you manage the project; having an envelope means your hours on that project are tracked against a plan. These are independent.</p></blockquote><p>The sum of all envelopes on a project should not exceed the project&#39;s total budget. VERA will warn you if it does, but it won&#39;t hard-block the creation.</p><hr><h2 id="envelopes-vs-assignments" tabindex="-1">Envelopes vs. assignments <a class="header-anchor" href="#envelopes-vs-assignments" aria-label="Permalink to &quot;Envelopes vs. assignments&quot;">​</a></h2><p>These terms are also used interchangeably in conversation, but they have a precise meaning in VERA:</p><ul><li><strong>Assignment</strong>: the state of having an envelope on a project — i.e. having at least one active envelope row</li><li><strong>Envelope</strong>: the specific record (with an hours amount and optional task tag)</li></ul><p>When someone asks &quot;who is on this project?&quot;, the answer is: everyone with an active envelope.</p><p>When someone asks &quot;what should I work on?&quot;, the answer is: your active envelopes — the projects you have envelopes on, with hours remaining.</p><hr><h2 id="envelopes-do-not-gate-time-logging" tabindex="-1">Envelopes do not gate time logging <a class="header-anchor" href="#envelopes-do-not-gate-time-logging" aria-label="Permalink to &quot;Envelopes do not gate time logging&quot;">​</a></h2><p>This is the most important thing to understand about envelopes:</p><p><strong>Anyone can log time to any active project, regardless of whether they have an envelope.</strong></p><p>Envelopes are a planning and visibility tool. They answer &quot;how was the work supposed to be distributed?&quot; — they are not an access control mechanism.</p><hr><h2 id="exception-based-approval" tabindex="-1">The envelope is the approval <a class="header-anchor" href="#exception-based-approval" aria-label="Permalink to &quot;The envelope is the approval {#exception-based-approval}&quot;">​</a></h2><p>VERA has no separate sign-off step for recorded time — a Manager doesn&#39;t review and click &quot;approve&quot; on every timesheet. Instead:</p><ul><li>Time logged <strong>inside an active envelope that still has room</strong> is <strong>approved automatically</strong>. Nothing is queued and nobody is asked — the Manager already approved this work when they created the envelope, and logging against it is executing a decision that was already made.</li><li>Time that is <strong>not covered by any envelope</strong>, or that <strong>pushes an envelope past its allocated hours</strong>, is surfaced as an exception in the <a href="/reference/tools/reports.html#get_unresolved_items">unresolved items queue</a> for a Manager to look at.</li></ul><p><strong>All recorded time counts in every report, approved or not.</strong> No dashboard, LER, margin, burn-up, or P&amp;L figure is ever filtered by approval state — this is a queue for a Manager&#39;s attention, not a gate on what&#39;s real.</p><p>Internal, PTO, sick, and leave time is exempt — those categories are evergreen and don&#39;t carry envelopes by design, so none of it generates an exception. A person&#39;s repeated logging against the same over-full or uncovered situation creates one open item, not one per entry — it stays open until a Manager resolves or dismisses it.</p><p>Time recorded on a company holiday is treated the same way — it isn&#39;t refused (VERA doesn&#39;t second-guess a genuine reason to work a holiday, like a launch or a client emergency), but it surfaces as its own exception so a Manager sees it. Logging more than once on the same holiday doesn&#39;t pile up separate items — the first one covers the day.</p><hr><h2 id="phrasing" tabindex="-1">Natural-language phrasing <a class="header-anchor" href="#phrasing" aria-label="Permalink to &quot;Natural-language phrasing {#phrasing}&quot;">​</a></h2><p>VERA accepts two word orders when creating an envelope — both are equivalent:</p><table tabindex="0"><thead><tr><th>Style</th><th>Example</th></tr></thead><tbody><tr><td>Natural (<code>to &lt;project&gt; for &lt;person&gt;</code>)</td><td><code>allocate 20h to Apex for Rachel as Design</code></td></tr><tr><td>Legacy (<code>to &lt;person&gt; on &lt;project&gt;</code>)</td><td><code>allocate 20h to Rachel on Apex for Design</code></td></tr></tbody></table><p>Either way, VERA binds each name to the slot matching what it actually is (person or project) in one turn — no follow-up questions when all slots are present in the opening sentence.</p><p>If a User logs time to a project they don&#39;t have an envelope on, VERA records it. If they log more hours than their envelope, VERA records it (and flags the overdraw). The system trusts that Managers are monitoring envelopes and responding to alerts.</p><hr><h2 id="lifetime-vs-period-scoped-envelopes" tabindex="-1">Lifetime vs. period-scoped envelopes <a class="header-anchor" href="#lifetime-vs-period-scoped-envelopes" aria-label="Permalink to &quot;Lifetime vs. period-scoped envelopes&quot;">​</a></h2><p>For most project types, an envelope is a <strong>project-lifetime budget</strong>: it covers the entire duration of that project, from start to finish.</p><p>For <strong>Retainer</strong> and <strong>Agile</strong> projects the model is different — and intentionally so.</p><h3 id="retainer-and-agile-envelopes-are-per-period" tabindex="-1">Retainer and Agile envelopes are per-period <a class="header-anchor" href="#retainer-and-agile-envelopes-are-per-period" aria-label="Permalink to &quot;Retainer and Agile envelopes are per-period&quot;">​</a></h3><p>Retainer and Agile projects run as a series of periods (monthly retainer periods, or sprint periods). Time entries are logged against the <strong>active period child</strong>, not the parent project directly. Envelopes follow the same pattern.</p><p>When you allocate hours to a Retainer or Agile project, VERA automatically routes the envelope to the <strong>active period child</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>allocate_hours(project=&quot;Nike Retainer&quot;, user=Alice, hours=60)</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>VERA finds the active period: &quot;Nike Retainer — April 2026&quot;</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>Envelope is stored against project_id 47 (the April period), not project_id 12 (the parent)</span></span></code></pre></div><p>This matters because:</p><ol><li><strong>Utilization is per-period.</strong> A retainer engagement aims for ~100% burn each month. An envelope scoped to the full retainer parent would never be exhaustible in a meaningful way — 60 hours against a two-year retainer means nothing. 60 hours against April means everything.</li><li><strong>Commitment changes between periods.</strong> In April a client takes 60 hours; in May they scale up to 80. Each new period can have its own envelope, reflecting the actual contracted commitment.</li><li><strong><code>hours_logged</code> is calculated correctly.</strong> Time entries reference the period child. If the envelope also references the period child, the logged vs. allocated comparison works. If the envelope were on the parent, <code>hours_logged</code> would always read as zero.</li></ol><h3 id="what-happens-at-period-rollover" tabindex="-1">What happens at period rollover <a class="header-anchor" href="#what-happens-at-period-rollover" aria-label="Permalink to &quot;What happens at period rollover&quot;">​</a></h3><p>When you close an April period and open a May period, the April envelopes remain — they&#39;re cancelled or archived when the period closes. To assign work in May, create new envelopes against the now-active May period.</p><p><strong>If there is no active period, <code>allocate_hours</code> returns an error.</strong> Create the next period first (<code>create_retainer_period</code> or <code>create_sprint</code>), then allocate.</p><p><strong>Both <code>allocate_hours</code> and <code>update_allocation</code> reject attempts to target a Retainer or Agile parent directly.</strong> The error message names the active period to guide the user toward the correct target.</p><h3 id="envelope-responses-for-retainer-agile" tabindex="-1">Envelope responses for Retainer/Agile <a class="header-anchor" href="#envelope-responses-for-retainer-agile" aria-label="Permalink to &quot;Envelope responses for Retainer/Agile&quot;">​</a></h3><p>When an envelope is created on a Retainer or Agile project, the response includes both the parent and period context:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;project_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">47</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;project_name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Nike Retainer&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;parent_project_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;period_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">47</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;period_name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Nike Retainer — April 2026&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;allocated_hours&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>project_name</code> is always the parent (what you asked about). <code>period_name</code> tells you which period the hours are committed to. <code>project_id</code> is the period child (where time entries are written).</p><h3 id="what-you-see-when-querying-your-own-envelopes" tabindex="-1">What you see when querying your own envelopes <a class="header-anchor" href="#what-you-see-when-querying-your-own-envelopes" aria-label="Permalink to &quot;What you see when querying your own envelopes&quot;">​</a></h3><p><code>get_my_allocations</code> and <code>get_my_assignments</code> always show <strong>parent project names</strong>. The <code>period_name</code> field is populated alongside when the envelope is period-scoped, so you can see which month or sprint it covers:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Nike Retainer   ← project_name (always the parent)</span></span>
<span class="line"><span>  period_name: &quot;Nike Retainer — April 2026&quot;</span></span>
<span class="line"><span>  allocated: 60h  logged: 42h  remaining: 18h</span></span></code></pre></div><hr><h2 id="envelope-fields" tabindex="-1">Envelope fields <a class="header-anchor" href="#envelope-fields" aria-label="Permalink to &quot;Envelope fields&quot;">​</a></h2><p>Each envelope has:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>Permanent sequential ID — use this to update or cancel</td></tr><tr><td><code>user_id</code></td><td>The person this envelope belongs to</td></tr><tr><td><code>project_id</code></td><td>The project or period child it targets</td></tr><tr><td><code>allocated_hours</code></td><td>Hours budgeted for this person on this project/period</td></tr><tr><td><code>task_id</code></td><td>Optional: work category tag (links to a task type)</td></tr><tr><td><code>status</code></td><td><code>active</code> or <code>cancelled</code></td></tr><tr><td><code>created_by</code></td><td>Manager or Owner who created the envelope</td></tr><tr><td><code>created_at</code></td><td>Date created</td></tr></tbody></table><p>The <code>task_id</code> tag constrains which task type the envelope can be created with: only tasks <strong>enabled for the project</strong> (via Edit tasks / <code>enable_task_for_project</code>) are valid at allocation time. A project with no enabled tasks cannot receive any envelope. The tag is planning metadata — it does not restrict what tasks the person logs against once work begins.</p><hr><h2 id="multiple-envelopes-on-the-same-task" tabindex="-1">Multiple envelopes on the same task <a class="header-anchor" href="#multiple-envelopes-on-the-same-task" aria-label="Permalink to &quot;Multiple envelopes on the same task&quot;">​</a></h2><p>A person can have more than one active envelope for the same project and task type. This happens when an allocation is topped up by creating a new envelope rather than updating the existing one.</p><p>VERA uses a <strong>bucket model</strong> to avoid double-counting logged hours in this situation. All envelopes sharing the same <code>(person, project, task)</code> triple are merged into a single row before any usage figure is computed:</p><ul><li><strong>Allocated hours</strong> = sum of all envelope allocations in the bucket</li><li><strong>Logged hours</strong> = total hours the person logged on that project/task — attributed to the bucket once, never split across individual envelopes</li></ul><p>This means <code>hours_logged</code> and <code>budget_remaining</code> are always accurate regardless of how many envelopes exist in the bucket.</p><p>In the web console and in <code>get_allocations</code> responses, a multi-envelope bucket shows a disclosure element listing each constituent envelope&#39;s ID and allocated hours. Each envelope retains its own Edit and Cancel modal so individual envelopes can still be adjusted.</p><hr><h2 id="budget-overdraw" tabindex="-1">Budget overdraw <a class="header-anchor" href="#budget-overdraw" aria-label="Permalink to &quot;Budget overdraw&quot;">​</a></h2><p>When a person has logged more hours than their allocated budget on a project, that is a <strong>budget overdraw</strong>.</p><p>VERA surfaces overdraws in morning and evening summaries, and via <code>get_estimates_vs_actuals</code>. A delta &gt; 0 means over-plan. Example:</p><blockquote><p>&quot;⚠️ Bob has logged 45h on Nike Rebrand but only has 40h in his envelope — 5h over.&quot;</p></blockquote><p>Overdraw doesn&#39;t block logging. It&#39;s a signal for the Manager to either update the envelope or have a scope conversation with the client. The log that crosses the line also opens an <code>envelope_overrun</code> item in the unresolved items queue (see <a href="#exception-based-approval">The envelope is the approval</a>) — its top resolution option raises the envelope to cover what&#39;s already logged.</p><hr><h2 id="capacity-and-overbooking" tabindex="-1">Capacity and overbooking <a class="header-anchor" href="#capacity-and-overbooking" aria-label="Permalink to &quot;Capacity and overbooking&quot;">​</a></h2><p><strong>Team availability</strong> is the aggregate view: for each person, how many hours are they allocated vs. how many are free.</p><p><strong>Overbooking</strong> happens when a person&#39;s total envelopes across all their projects exceed their available capacity.</p><p><strong>How capacity is calculated:</strong></p><p>VERA calculates available capacity from two sources: the user&#39;s individual <code>hours_per_week</code> setting, and the calendar. The formula is:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>available hours = (working days × hours_per_day) − company holidays − time off</span></span>
<span class="line"><span></span></span>
<span class="line"><span>where: hours_per_day = user.hours_per_week ÷ work_days_per_week</span></span></code></pre></div><p>Time-off hours (sick, leave, PTO) are capped at the user&#39;s <code>hours_per_day</code> per entry. This ensures a sick day logged at a standard 8-hour block doesn&#39;t over-subtract from a contractor whose working day is shorter.</p><p><strong><code>hours_per_week</code> is set per person:</strong></p><ul><li><strong>FTE</strong>: defaults to 40. No need to specify when adding a user.</li><li><strong>Contractor</strong>: must be set explicitly when adding the user. A contractor doing 3 days a week at standard hours would be 24. VERA will ask for this when you add a contractor.</li><li><strong>Vendor</strong>: placeholder value of 40. Vendor capacity is not tracked meaningfully — cost is governed by liabilities, not hours.</li></ul><p>The work week schedule (which days count, and how many hours per day for the base calculation) is configured at the tenant level via <code>set_work_week</code>, defaulting to Mon–Fri. Company holidays from <code>12. Company_Calendar</code> and approved time off already logged are both subtracted.</p><p>The overbooking check uses a rolling <strong>90-day window</strong> from today. This means capacity is compared against available working time in the next 3 months, not against a single day or week.</p><p>VERA detects overbooking when you create or update an envelope via <code>allocate_hours</code>. If the envelope would put someone over capacity in the 90-day window, VERA returns <code>overbooked: true</code> and flags the person and hours over. This doesn&#39;t block the creation — it&#39;s a warning.</p><p>Use <code>get_team_availability</code> to see everyone&#39;s headroom across all projects. Use <code>check_capacity</code> when evaluating whether the team can take on new work.</p><hr><h2 id="envelope-lifecycle" tabindex="-1">Envelope lifecycle <a class="header-anchor" href="#envelope-lifecycle" aria-label="Permalink to &quot;Envelope lifecycle&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>allocate_hours → active envelope</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>update_allocation → change hours (up or down)</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>cancel_allocation → envelope marked cancelled (not deleted)</span></span></code></pre></div><p>Cancelled envelopes are kept for audit trail purposes. When you query envelopes, VERA returns only active ones by default.</p><hr><h2 id="envelope-model-by-project-type" tabindex="-1">Envelope model by project type <a class="header-anchor" href="#envelope-model-by-project-type" aria-label="Permalink to &quot;Envelope model by project type&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Project type</th><th>Envelope scope</th><th>Notes</th></tr></thead><tbody><tr><td>T&amp;M</td><td>Project lifetime</td><td>Covers all time logged to the project</td></tr><tr><td>Fixed Price</td><td>Project lifetime</td><td>Covers all time logged to the project</td></tr><tr><td>Pro Bono</td><td>Project lifetime</td><td>No revenue; envelope tracks effort only</td></tr><tr><td>Internal</td><td>Project lifetime</td><td>Overhead/admin; no financial tracking</td></tr><tr><td><strong>Retainer</strong></td><td><strong>Active period child</strong></td><td>New envelope required each period; error if no active period</td></tr><tr><td><strong>Agile</strong></td><td><strong>Active sprint child</strong></td><td>New envelope required each sprint; error if no active sprint</td></tr></tbody></table><p>For Retainer and Agile, the parent project acts as a roll-up label. All time and envelopes live on the individual period/sprint children.</p><hr><h2 id="common-envelope-queries" tabindex="-1">Common envelope queries <a class="header-anchor" href="#common-envelope-queries" aria-label="Permalink to &quot;Common envelope queries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Question</th><th>Tool</th></tr></thead><tbody><tr><td>&quot;What should I work on?&quot;</td><td><code>get_my_assignments</code></td></tr><tr><td>&quot;What are Alice&#39;s envelopes?&quot;</td><td><code>get_person_allocation_summary</code></td></tr><tr><td>&quot;Who is on the Nike project?&quot;</td><td><code>get_project_assignments</code></td></tr><tr><td>&quot;How much headroom does the team have?&quot;</td><td><code>get_team_availability</code></td></tr><tr><td>&quot;How did plan vs actual compare last week?&quot;</td><td><code>get_estimates_vs_actuals</code></td></tr><tr><td>&quot;Can we take on new work in April?&quot;</td><td><code>check_capacity</code></td></tr><tr><td>&quot;What&#39;s the 4-week capacity outlook?&quot;</td><td><code>get_capacity_forecast</code></td></tr></tbody></table>`,102)])])}const u=t(s,[["render",r]]);export{g as __pageData,u as default};
